/// Simulate a vending machine and return the messages it prints, in order.
/// Slot k (0-based) sells an item for prices[k] cents (a positive multiple of 5) and
/// holds stock[k] items. Credit starts at 0. An event is words separated by single
/// spaces; an integer argument is an optional '-' then 1 to 9 ASCII digits.
/// - "coin V": V in 5, 10, 25, 100 adds V to the credit and prints nothing. Any other
///   integer V, or a coin that would raise the credit above 500, prints "reject V"
///   and leaves the credit unchanged.
/// - "select K": if K is not a slot, print "no slot K"; else if the slot is empty,
///   print "sold out K"; else if the credit is below the price, print "insert D"
///   (D is the missing amount); else print "vend K", remove one item from the slot,
///   subtract the price from the credit and, if credit remains, return it as change.
/// - "refund": return the credit as change, or print "nothing" if the credit is 0.
/// - Anything else (unknown word, missing, extra or malformed argument) prints
///   "error" and changes nothing.
/// Returning change prints "change " then the coins joined by "+", largest first,
/// using as many 100s as possible, then 25s, 10s, 5s; the credit becomes 0.
/// >>> vending_machine(vec![65], vec![2], vec![String::from("coin 100"), String::from("select 0")])
/// vec![String::from("vend 0"), String::from("change 25+10")]
/// >>> vending_machine(vec![50, 30], vec![1, 0], vec![String::from("coin 25"), String::from("select 0"), String::from("select 1"), String::from("refund"), String::from("refund")])
/// vec![String::from("insert 25"), String::from("sold out 1"), String::from("change 25"), String::from("nothing")]
fn vending_machine(prices: Vec<isize>, stock: Vec<isize>, events: Vec<String>) -> Vec<String> {
    let mut stock = stock;
    let mut credit: isize = 0;
    let mut out: Vec<String> = Vec::new();
    for event in events.iter() {
        let words: Vec<&str> = event.split(' ').collect();
        let arg = if words.len() == 2 { parse_arg(words[1]) } else { None };
        if words == vec!["refund"] {
            out.push(if credit > 0 { change_msg(credit) } else { "nothing".to_string() });
            credit = 0;
            continue;
        }
        match (words[0], arg) {
            ("coin", Some(v)) => {
                if [5, 10, 25, 100].contains(&v) && credit + v <= 500 {
                    credit += v;
                } else {
                    out.push(format!("reject {}", v));
                }
            }
            ("select", Some(k)) => {
                if k < 0 || k >= prices.len() as isize {
                    out.push(format!("no slot {}", k));
                } else if stock[k as usize] == 0 {
                    out.push(format!("sold out {}", k));
                } else if credit < prices[k as usize] {
                    out.push(format!("insert {}", prices[k as usize] - credit));
                } else {
                    out.push(format!("vend {}", k));
                    stock[k as usize] -= 1;
                    credit -= prices[k as usize];
                    if credit > 0 {
                        out.push(change_msg(credit));
                        credit = 0;
                    }
                }
            }
            _ => out.push("error".to_string()),
        }
    }
    out
}

fn parse_arg(word: &str) -> Option<isize> {
    let digits = word.strip_prefix('-').unwrap_or(word);
    if digits.is_empty() || digits.len() > 9 || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    word.parse().ok()
}

fn change_msg(amount: isize) -> String {
    let mut left = amount;
    let mut coins: Vec<String> = Vec::new();
    for coin in [100, 25, 10, 5] {
        while left >= coin {
            coins.push(coin.to_string());
            left -= coin;
        }
    }
    format!("change {}", coins.join("+"))
}
